    ('010a1ed2-823c-580c-96a9-35ca75824f01'::uuid, 'Quiz — For, since, ago, how long', 'Anglais', '4e', 'Exprimer la durée', 'ddab6876-fa67-5830-8bac-53eab355324a'::uuid),
