  ) AS v(id, title, subject, grade_level, chapter, lesson_id)
  JOIN public.lessons l ON l.id = v.lesson_id
 WHERE NOT EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.lesson_id = l.id)
ON CONFLICT (id) DO NOTHING;

-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('542eef0d-1aab-5bbf-96aa-88dde25c738d'::uuid, '4f0d3b81-8343-57c9-9ab0-c1b573ed1d60'::uuid, 'Quel est le pluriel de « child » ?', 'mcq', '["children","childs","childes","childrens"]'::jsonb, 0, 'C’est l’un des pluriels irréguliers les plus fréquents.', 1),
    ('235d2a13-f474-5981-88ec-8a50d2647b0e'::uuid, '4f0d3b81-8343-57c9-9ab0-c1b573ed1d60'::uuid, 'Quel est le pluriel de « city » ?', 'mcq', '["cities","citys","cityes","cityies"]'::jsonb, 0, 'Consonne + y donne -ies ; « boy » fait « boys » car le y suit une voyelle.', 2),
    ('6fdf91cd-a192-5c11-8833-422916c9a56b'::uuid, '4f0d3b81-8343-57c9-9ab0-c1b573ed1d60'::uuid, 'Quelle phrase est correcte ?', 'mcq', '["I need some advice.","I need an advice.","I need some advices.","I need two advices."]'::jsonb, 0, '« Advice » est indénombrable : on dit « a piece of advice ».', 3),
    ('fa2af798-1f29-554c-96d6-f9b1d23df62e'::uuid, '4f0d3b81-8343-57c9-9ab0-c1b573ed1d60'::uuid, 'Comment compte-t-on un nom indénombrable ?', 'mcq', '["En employant un partitif, comme « a piece of »","En ajoutant -s","En le faisant précéder de « a »","C’est impossible"]'::jsonb, 0, 'A glass of water, a piece of furniture.', 4),
    ('07bf5ea9-e988-583d-9319-bfda41d8f5cf'::uuid, '4f0d3b81-8343-57c9-9ab0-c1b573ed1d60'::uuid, 'Quel verbe accompagne « the news » ?', 'mcq', '["is","are","were","have"]'::jsonb, 0, 'Malgré le -s final, « news » est indénombrable et singulier.', 5),
    ('d2790170-de44-50b6-bfb3-305e2411fb74'::uuid, '4f0d3b81-8343-57c9-9ab0-c1b573ed1d60'::uuid, 'Quel est le pluriel de « knife » ?', 'mcq', '["knives","knifes","knifs","knifves"]'::jsonb, 0, 'Les noms en -f ou -fe font souvent leur pluriel en -ves.', 6),
    ('a23f0fb4-6b33-5f1c-9c0f-7c78cc81dc71'::uuid, '4f0d3b81-8343-57c9-9ab0-c1b573ed1d60'::uuid, 'Comment exprime-t-on la possession avec un nom animé ?', 'mcq', '["Avec ’s : my sister’s phone","Avec « of » uniquement","En inversant les deux noms sans marque","Avec « to » devant le possesseur"]'::jsonb, 0, 'Au pluriel en -s, on met l’apostrophe seule : the students’ books.', 7),
    ('1b5262d0-12f0-5c31-98e8-59a9a8825256'::uuid, '4f0d3b81-8343-57c9-9ab0-c1b573ed1d60'::uuid, '« Furniture » peut se mettre au pluriel en anglais.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un indénombrable : on dit « two pieces of furniture ».', 8),
    ('a1b68198-78be-5182-b21a-74632be88596'::uuid, 'ba877f9f-761f-5fe1-94ef-aba6ec58b90a'::uuid, 'Quand emploie-t-on « an » plutôt que « a » ?', 'mcq', '["Devant un son de voyelle","Devant la lettre A, E, I, O ou U","Devant un nom pluriel","Devant un nom propre"]'::jsonb, 0, '« An hour » (h muet) mais « a university » (son « you »).', 1),
    ('628071d0-caea-5aa1-9a3e-55c52b21dec7'::uuid, 'ba877f9f-761f-5fe1-94ef-aba6ec58b90a'::uuid, 'Quelle phrase est correcte ?', 'mcq', '["She is a dentist.","She is dentist.","She is the dentist by profession.","She is an dentist."]'::jsonb, 0, 'Le métier prend l’article indéfini en anglais.', 2),
    ('9739229a-80c1-5b27-b3a2-c42ed852872e'::uuid, 'ba877f9f-761f-5fe1-94ef-aba6ec58b90a'::uuid, 'Comment traduit-on « J’aime les chiens » ?', 'mcq', '["I like dogs.","I like the dogs.","I like a dogs.","I like some the dogs."]'::jsonb, 0, 'Un pluriel au sens général ne prend aucun article.', 3),
    ('101b87f3-42e1-52f5-bcc6-a8a9e804510f'::uuid, 'ba877f9f-761f-5fe1-94ef-aba6ec58b90a'::uuid, 'Quelle phrase est correcte ?', 'mcq', '["I play the piano and I play football.","I play piano and I play the football.","I play the piano and I play the football.","I play piano and I play football."]'::jsonb, 0, 'Instrument de musique avec « the », sport sans article.', 4),
    ('7ff7fa5c-9dcb-5b8d-b6f3-3b7aef49ac38'::uuid, 'ba877f9f-761f-5fe1-94ef-aba6ec58b90a'::uuid, 'Devant quel type de nom géographique emploie-t-on « the » ?', 'mcq', '["Les fleuves, océans et chaînes de montagnes","Les villes","Les pays au singulier","Les continents"]'::jsonb, 0, 'The Thames, the Atlantic, the Alps, the Netherlands.', 5),
    ('950350f8-f780-58e9-9514-a65bde85a124'::uuid, 'ba877f9f-761f-5fe1-94ef-aba6ec58b90a'::uuid, 'Comment traduit-on « deux fois par semaine » ?', 'mcq', '["twice a week","twice the week","twice week","two times the week"]'::jsonb, 0, 'L’article indéfini exprime la fréquence.', 6),
    ('2f560607-00cc-5383-8e67-fd8643200c6f'::uuid, 'ba877f9f-761f-5fe1-94ef-aba6ec58b90a'::uuid, 'Quelle différence y a-t-il entre « go to school » et « go to the school » ?', 'mcq', '["Le premier désigne l’activité d’étudier, le second le bâtiment précis","Le premier est familier, le second soutenu","Les deux sont identiques","Le second est incorrect"]'::jsonb, 0, 'Même distinction pour « hospital » ou « church ».', 7),
    ('6b0260a4-bad7-5d19-a605-83a7d42f840b'::uuid, 'ba877f9f-761f-5fe1-94ef-aba6ec58b90a'::uuid, 'C’est la première lettre du mot qui décide entre « a » et « an ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est le son : « an hour » commence par un h muet, « a university » par un son « you ».', 8),
    ('c2b7e5f1-e1fe-57fe-84fd-1b16527431ae'::uuid, '4dd0a37a-a8e3-5843-b647-1d983d9d8683'::uuid, 'Quel démonstratif emploie-t-on pour un objet proche au pluriel ?', 'mcq', '["these","this","those","that"]'::jsonb, 0, '« These shoes are new. »', 1),
    ('143da752-704d-5a4e-a5a0-833fb2392f35'::uuid, '4dd0a37a-a8e3-5843-b647-1d983d9d8683'::uuid, 'Quel démonstratif emploie-t-on pour un objet éloigné au singulier ?', 'mcq', '["that","this","these","those"]'::jsonb, 0, '« That house over there is old. »', 2),
    ('c47ef148-b8fd-5f82-b280-25b1da0ac28e'::uuid, '4dd0a37a-a8e3-5843-b647-1d983d9d8683'::uuid, 'Quelle phrase est correcte ?', 'mcq', '["These children are noisy.","This children are noisy.","Thoses children are noisy.","That children are noisy."]'::jsonb, 0, 'Le démonstratif s’accorde en nombre avec le nom.', 3),
    ('0dd5f494-35fe-5dce-bf3e-7eec023bdf74'::uuid, '4dd0a37a-a8e3-5843-b647-1d983d9d8683'::uuid, 'Quel démonstratif emploie-t-on pour parler de ce matin ?', 'mcq', '["this morning","that morning","these morning","those morning"]'::jsonb, 0, '« This » vaut aussi pour la proximité dans le temps.', 4),
    ('8517052a-ad79-5331-9e17-40b276ea071b'::uuid, '4dd0a37a-a8e3-5843-b647-1d983d9d8683'::uuid, 'Comment se présente-t-on au téléphone en anglais ?', 'mcq', '["This is Paul speaking.","It is Paul speaking.","That is Paul speaking.","Here Paul speaking."]'::jsonb, 0, 'L’anglais emploie le démonstratif là où le français dit « c’est ».', 5),
    ('f7f38da6-201c-5a08-987e-b819aa9c3d56'::uuid, '4dd0a37a-a8e3-5843-b647-1d983d9d8683'::uuid, 'Quelle est la différence entre un démonstratif adjectif et pronom ?', 'mcq', '["L’adjectif est suivi d’un nom, le pronom s’emploie seul","L’adjectif est toujours au pluriel","Le pronom se place après le verbe","Il n’y a aucune différence"]'::jsonb, 0, '« This car » contre « This is my car ».', 6),
    ('ede75f7c-449a-57af-a591-aac393ccdd71'::uuid, '4dd0a37a-a8e3-5843-b647-1d983d9d8683'::uuid, 'Quel démonstratif emploie-t-on pour un souvenir lointain au pluriel ?', 'mcq', '["those","these","that","this"]'::jsonb, 0, '« Those were the days. »', 7),
    ('5a3728e9-0ae0-51b6-aa60-4063124303e4'::uuid, '4dd0a37a-a8e3-5843-b647-1d983d9d8683'::uuid, '« Those » peut s’écrire « thoses » au pluriel.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est déjà pluriel : les démonstratifs ne prennent jamais de -s supplémentaire.', 8),
    ('c88c62a5-0864-561f-a481-756819c2cdba'::uuid, 'f97e9263-a7d8-5d59-bbf2-31e70c76178e'::uuid, 'Comment traduit-on « la voiture de mon père » ?', 'mcq', '["my father’s car","the car of my father","my father car","the father’s my car"]'::jsonb, 0, 'L’ordre est inverse du français : possesseur + ’s + objet.', 1),
    ('ce05c0c0-c0e7-5aa9-b829-e26b503bb89c'::uuid, 'f97e9263-a7d8-5d59-bbf2-31e70c76178e'::uuid, 'Comment écrit-on « la chambre des filles » ?', 'mcq', '["the girls’ room","the girl’s room","the girls’s room","the room of girls"]'::jsonb, 0, 'Pluriel déjà en -s : l’apostrophe seule suffit.', 2),
    ('a54df2e4-fe92-5a93-9932-fbfc8b75c050'::uuid, 'f97e9263-a7d8-5d59-bbf2-31e70c76178e'::uuid, 'Comment écrit-on « les jouets des enfants » ?', 'mcq', '["the children’s toys","the childrens’ toys","the children toys","the toys of children"]'::jsonb, 0, 'Pluriel irrégulier : on ajoute ’s normalement.', 3),
    ('5c1f73ab-24e8-514a-a47a-7e90b8b6b7dd'::uuid, 'f97e9263-a7d8-5d59-bbf2-31e70c76178e'::uuid, 'Quel possessif emploie-t-on avec un objet inanimé ?', 'mcq', '["La structure avec « of » : the roof of the house","Toujours ’s","Toujours « its »","Aucun possessif n’est possible"]'::jsonb, 0, 'Le génitif ’s est réservé surtout aux êtres animés et au temps.', 4),
    ('3fd9a420-4dce-57b9-89d9-71d624c051cf'::uuid, 'f97e9263-a7d8-5d59-bbf2-31e70c76178e'::uuid, 'Quelle phrase est correcte ?', 'mcq', '["This book is mine.","This book is my.","This is mine book.","This book is my one."]'::jsonb, 0, 'Le pronom possessif n’est jamais suivi d’un nom.', 5),
    ('8d8a587f-7c33-587f-90c7-44498e0f94e2'::uuid, 'f97e9263-a7d8-5d59-bbf2-31e70c76178e'::uuid, 'Avec quoi le possessif s’accorde-t-il en anglais ?', 'mcq', '["Avec le possesseur","Avec l’objet possédé","Avec le verbe","Avec le sujet de la phrase"]'::jsonb, 0, '« Paul and his sister », « Kate and her brother ».', 6),
    ('a58b31a2-d6d4-551a-99df-a5b254736b10'::uuid, 'f97e9263-a7d8-5d59-bbf2-31e70c76178e'::uuid, 'Quelle est la différence entre « its » et « it’s » ?', 'mcq', '["« its » est le possessif, « it’s » la contraction de « it is »","« its » est la contraction de « it is »","Les deux sont interchangeables","« it’s » est le possessif au pluriel"]'::jsonb, 0, 'L’apostrophe marque la contraction, jamais le possessif de « it ».', 7),
    ('fb078c2d-f003-5d0d-9af3-e6b9a37e8adb'::uuid, 'f97e9263-a7d8-5d59-bbf2-31e70c76178e'::uuid, 'On dit « the car of my father » pour traduire « la voiture de mon père ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Avec un être animé, l’anglais emploie le génitif : « my father’s car ».', 8),
    ('569c2dc8-a403-5364-8251-f1fed4ea721c'::uuid, 'f0ae63d7-22ad-5903-9f27-3db89462d0d9'::uuid, 'Quel quantifieur emploie-t-on dans une phrase négative ?', 'mcq', '["any","some","much of","a few"]'::jsonb, 0, '« I don’t have any money. »', 1),
    ('82558745-729a-5b95-8a93-a293e39bf1f1'::uuid, 'f0ae63d7-22ad-5903-9f27-3db89462d0d9'::uuid, 'Quel quantifieur emploie-t-on avec un nom indénombrable dans une question ?', 'mcq', '["much","many","a few","several"]'::jsonb, 0, '« How much water? » contre « How many books? »', 2),
    ('e6b44df5-bec3-51a0-9b9c-4a06d024482e'::uuid, 'f0ae63d7-22ad-5903-9f27-3db89462d0d9'::uuid, 'Que signifie « a few friends » ?', 'mcq', '["Quelques amis, un nombre suffisant","Trop peu d’amis","Aucun ami","Beaucoup d’amis"]'::jsonb, 0, 'Sans l’article, « few friends » a un sens négatif.', 3),
    ('f26b230e-3186-5b67-97da-198ad35c4ee9'::uuid, 'f0ae63d7-22ad-5903-9f27-3db89462d0d9'::uuid, 'Quel quantifieur emploie-t-on avec un indénombrable pour dire « un peu de » ?', 'mcq', '["a little","a few","many","several"]'::jsonb, 0, '« A little time », « a few minutes ».', 4),
    ('905c61ff-bd5f-5e80-b3e8-fbb3110406d7'::uuid, 'f0ae63d7-22ad-5903-9f27-3db89462d0d9'::uuid, 'Quelle phrase propose poliment quelque chose ?', 'mcq', '["Would you like some tea?","Would you like any tea?","Do you like some tea?","Would you like much tea?"]'::jsonb, 0, '« Some » s’emploie dans les offres et demandes polies.', 5),
    ('2cd5fd26-4786-5e5c-a59c-ed1f0582275f'::uuid, 'f0ae63d7-22ad-5903-9f27-3db89462d0d9'::uuid, 'Que signifie « any » dans une phrase affirmative ?', 'mcq', '["N’importe quel","Aucun","Beaucoup de","Quelques"]'::jsonb, 0, '« Take any book you like. »', 6),
    ('61b03c66-132f-509c-967f-928e56078365'::uuid, 'f0ae63d7-22ad-5903-9f27-3db89462d0d9'::uuid, 'Quel quantifieur remplace « much » et « many » à l’affirmative ?', 'mcq', '["a lot of","any","no","each"]'::jsonb, 0, 'Il fonctionne avec les dénombrables comme avec les indénombrables.', 7),
    ('21cc8b2a-1f4c-5ce3-bf6f-16f1e9efcb4c'::uuid, 'f0ae63d7-22ad-5903-9f27-3db89462d0d9'::uuid, '« Few » et « a few » ont exactement le même sens.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '« A few » signifie « quelques, assez » ; « few » signifie « trop peu ».', 8),
    ('e0b6638a-d9df-5c37-b26e-0faf842a0fa7'::uuid, 'c8c34e75-fa6c-5f62-82da-742dd390b976'::uuid, 'Où se place l’adjectif en anglais ?', 'mcq', '["Avant le nom","Après le nom","À la fin de la phrase","Cela dépend de son sens"]'::jsonb, 0, '« A beautiful house », l’inverse du français.', 1),
    ('2e4dd2f0-d141-5a3b-8dfb-074d9f60c121'::uuid, 'c8c34e75-fa6c-5f62-82da-742dd390b976'::uuid, 'Comment l’adjectif anglais s’accorde-t-il ?', 'mcq', '["Il est invariable","Il s’accorde en nombre","Il s’accorde en genre","Il s’accorde en genre et en nombre"]'::jsonb, 0, '« Two red cars », sans -s à l’adjectif.', 2),
    ('913eee51-c644-55ce-bd25-d7f85e107b43'::uuid, 'c8c34e75-fa6c-5f62-82da-742dd390b976'::uuid, 'Que signifie « I am bored » ?', 'mcq', '["Je m’ennuie","Je suis ennuyeux","J’ennuie les autres","Je suis fatigant"]'::jsonb, 0, 'La forme en -ed décrit ce que ressent la personne.', 3),
    ('0f926477-0ada-5319-a956-5292d42941b7'::uuid, 'c8c34e75-fa6c-5f62-82da-742dd390b976'::uuid, 'Comment dit-on « le film est ennuyeux » ?', 'mcq', '["The film is boring.","The film is bored.","The film is boredom.","The film is bore."]'::jsonb, 0, 'La forme en -ing décrit ce qui provoque le sentiment.', 4),
    ('7d0feada-e218-54e8-956d-c1f72c9de40a'::uuid, 'c8c34e75-fa6c-5f62-82da-742dd390b976'::uuid, 'Quel est l’ordre correct des adjectifs ?', 'mcq', '["a small old black car","a black old small car","an old black small car","a black small old car"]'::jsonb, 0, 'Taille, puis âge, puis couleur.', 5),
    ('9fcb0242-a556-5d0c-bf19-8e5d53aa6326'::uuid, 'c8c34e75-fa6c-5f62-82da-742dd390b976'::uuid, 'Comment écrit-on « un garçon de cinq ans » ?', 'mcq', '["a five-year-old boy","a five-years-old boy","a five year old boy","a boy of five years old"]'::jsonb, 0, 'Adjectif composé : traits d’union et nom au singulier.', 6),
    ('97f2a2f9-5ff2-5b3b-ba4f-3fe54a722e1a'::uuid, 'c8c34e75-fa6c-5f62-82da-742dd390b976'::uuid, 'Après quels verbes l’adjectif peut-il se placer ?', 'mcq', '["Après be, seem, look, feel, become","Après tous les verbes","Après les verbes d’action uniquement","Jamais après un verbe"]'::jsonb, 0, 'Ce sont les verbes d’état : « She looks tired. »', 7),
    ('f11e0a8f-daa1-5a96-ad64-8f9abf476a5a'::uuid, 'c8c34e75-fa6c-5f62-82da-742dd390b976'::uuid, '« The poor » se construit avec un verbe au singulier.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Un adjectif substantivé désigne un groupe : le verbe se met au pluriel.', 8),
    ('3c8a8805-750a-5f1b-80ff-1286eb0889ad'::uuid, '07b222c9-06a9-5f67-ae3f-0769795136d5'::uuid, 'À quoi servent les auxiliaires ?', 'mcq', '["À construire la question, la négation et la reprise courte","À donner le sens principal du verbe","À accorder le verbe avec le sujet","À former le pluriel"]'::jsonb, 0, 'Les verbes lexicaux, eux, portent le sens.', 1),
    ('80d9deff-dd86-5fda-9106-56757d139ab4'::uuid, '07b222c9-06a9-5f67-ae3f-0769795136d5'::uuid, 'Quel auxiliaire forme les temps en -ING et la voix passive ?', 'mcq', '["be","have","do","will"]'::jsonb, 0, '« She is working », « It was built ».', 2),
    ('011aad63-0e4e-51a9-ac0b-1b9c8684f6b6'::uuid, '07b222c9-06a9-5f67-ae3f-0769795136d5'::uuid, 'Quel auxiliaire forme les temps composés ?', 'mcq', '["have","be","do","can"]'::jsonb, 0, '« I have finished. »', 3),
    ('3cd860ed-1b85-530a-a800-c01a7018aff1'::uuid, '07b222c9-06a9-5f67-ae3f-0769795136d5'::uuid, 'À quoi sert l’auxiliaire « do » ?', 'mcq', '["À la négation, à l’interrogation et à l’insistance aux temps simples","À former le passif","À former le present perfect","À exprimer la capacité"]'::jsonb, 0, '« I don’t know », « Do you know? »', 4),
    ('c19c137d-415f-5187-9579-b56dced0474e'::uuid, '07b222c9-06a9-5f67-ae3f-0769795136d5'::uuid, 'Où se place l’auxiliaire dans une question ?', 'mcq', '["Devant le sujet","Après le verbe","À la fin de la phrase","Il disparaît"]'::jsonb, 0, '« Are you ready? », « Have you finished? »', 5),
    ('5ff2467b-1e46-5ffc-991a-b9de7cd8317e'::uuid, '07b222c9-06a9-5f67-ae3f-0769795136d5'::uuid, 'Où se place « not » dans une négation ?', 'mcq', '["Juste après l’auxiliaire","Avant l’auxiliaire","Après le verbe lexical","À la fin de la phrase"]'::jsonb, 0, 'isn’t, hasn’t, doesn’t, can’t.', 6),
    ('62e2f3df-9805-599b-9960-623360c93bdd'::uuid, '07b222c9-06a9-5f67-ae3f-0769795136d5'::uuid, 'Comment répond-on brièvement à « Do you like tea? » ?', 'mcq', '["Yes, I do.","Yes, I like.","Yes, I am.","Yes, I have."]'::jsonb, 0, 'La reprise courte réutilise l’auxiliaire de la question.', 7),
    ('b54bffc1-bf39-5ca8-8679-84d8d746ffd3'::uuid, '07b222c9-06a9-5f67-ae3f-0769795136d5'::uuid, '« Have » au sens de posséder se construit sans auxiliaire dans une question.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est alors lexical et demande « do » : « Do you have a car? »', 8),
    ('814c9444-a1b7-5d0e-a8c6-fb033a535fdf'::uuid, 'adbb4df5-4281-5659-bfa8-84c219ee2559'::uuid, 'Comment dit-on « J’ai 15 ans » ?', 'mcq', '["I am 15.","I have 15.","I have 15 years.","I am 15 years."]'::jsonb, 0, 'L’anglais emploie « be » là où le français emploie « avoir ».', 1),
    ('da6cfb05-22b5-5c1c-9142-806c70bc501d'::uuid, 'adbb4df5-4281-5659-bfa8-84c219ee2559'::uuid, 'Quelle est la forme de « be » au prétérit avec « they » ?', 'mcq', '["were","was","been","are"]'::jsonb, 0, 'I, he, she, it prennent « was ».', 2),
    ('6a0ef752-6268-5154-a6fd-c173320ec027'::uuid, 'adbb4df5-4281-5659-bfa8-84c219ee2559'::uuid, 'Quel est le participe passé de « be » ?', 'mcq', '["been","was","being","be"]'::jsonb, 0, '« I have been to London. »', 3),
    ('c5e38f0b-30e3-54c7-998e-26950a5af5d4'::uuid, 'adbb4df5-4281-5659-bfa8-84c219ee2559'::uuid, 'Quelle est la forme de « have » à la troisième personne du singulier au présent ?', 'mcq', '["has","have","haves","had"]'::jsonb, 0, '« She has a bike. »', 4),
    ('c5bc3252-0eee-508c-8290-4b8c918043e4'::uuid, 'adbb4df5-4281-5659-bfa8-84c219ee2559'::uuid, 'Comment interroge-t-on avec « have got » ?', 'mcq', '["Have you got a bike?","Do you have got a bike?","Do you got a bike?","Are you got a bike?"]'::jsonb, 0, '« Have got » se passe de « do » : l’auxiliaire est déjà là.', 5),
    ('bf192289-d147-50a3-8559-4dce0ddc133d'::uuid, 'adbb4df5-4281-5659-bfa8-84c219ee2559'::uuid, 'Quel auxiliaire forme la voix passive ?', 'mcq', '["be","have","do","will"]'::jsonb, 0, '« The window was broken. »', 6),
    ('620bbaf7-fce3-5fad-b941-f66d9dae4ba9'::uuid, 'adbb4df5-4281-5659-bfa8-84c219ee2559'::uuid, 'Que peut signifier la contraction « he’s » ?', 'mcq', '["« he is » ou « he has »","« he is » uniquement","« he has » uniquement","« he was »"]'::jsonb, 0, 'C’est ce qui suit qui tranche : « he’s tired » ou « he’s finished ».', 7),
    ('131efb99-7144-5001-ad31-a15927db239e'::uuid, 'adbb4df5-4281-5659-bfa8-84c219ee2559'::uuid, '« Have » est toujours un auxiliaire.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est lexical dans « I have a bike » ou « have breakfast ».', 8),
    ('39d92ca5-6954-5926-89cc-6e5f7bd5c25b'::uuid, 'b1c02179-f576-52e9-9da6-2254de57d679'::uuid, 'Dans quels cas l’auxiliaire DO apparaît-il ?', 'mcq', '["À la négation, à l’interrogation et à l’insistance","Dans toutes les phrases","Seulement au passé","Seulement avec les modaux"]'::jsonb, 0, 'Aux temps simples uniquement.', 1),
    ('ab80e317-9806-5ba3-8601-a7f8a8f59433'::uuid, 'b1c02179-f576-52e9-9da6-2254de57d679'::uuid, 'Quelle phrase est correcte ?', 'mcq', '["She doesn’t work here.","She doesn’t works here.","She don’t works here.","She not work here."]'::jsonb, 0, 'DO porte la marque de la personne, le verbe revient à la base verbale.', 2),
    ('6c64c694-c10f-5543-8679-a312c974a7e3'::uuid, 'b1c02179-f576-52e9-9da6-2254de57d679'::uuid, 'Comment met-on « He went » à la forme négative ?', 'mcq', '["He didn’t go.","He didn’t went.","He not went.","He doesn’t went."]'::jsonb, 0, 'Une phrase ne porte qu’une seule marque de temps.', 3),
    ('39752fc2-7bc6-5088-88ec-669317dbb388'::uuid, 'b1c02179-f576-52e9-9da6-2254de57d679'::uuid, 'Quelle question est correcte ?', 'mcq', '["Did you go to school?","Did you went to school?","Do you went to school?","You did go to school?"]'::jsonb, 0, 'DID porte le passé, le verbe reste à la base verbale.', 4),
    ('2aa60f0f-b3c3-5b03-83f2-4004c3ecbd4b'::uuid, 'b1c02179-f576-52e9-9da6-2254de57d679'::uuid, 'Avec quel verbe l’auxiliaire DO n’apparaît-il jamais ?', 'mcq', '["be","work","go","like"]'::jsonb, 0, '« Be » est son propre auxiliaire : « Is she a teacher? »', 5),
    ('472258c5-fe53-53b2-a018-ba7f7a3bdba2'::uuid, 'b1c02179-f576-52e9-9da6-2254de57d679'::uuid, 'Que signifie « I do like it » ?', 'mcq', '["J’aime vraiment ça : c’est une insistance","Je fais ce que j’aime","Je n’aime pas ça","C’est une question"]'::jsonb, 0, 'La forme emphatique s’accentue à l’oral.', 6),
    ('acf63cef-3d87-5410-86e8-628613249308'::uuid, 'b1c02179-f576-52e9-9da6-2254de57d679'::uuid, 'Quand « who » est sujet de la question, emploie-t-on DO ?', 'mcq', '["Non : « Who broke the window? »","Oui, toujours","Oui, seulement au passé","Oui, seulement au présent"]'::jsonb, 0, 'Le sujet étant déjà en tête, l’ordre n’a pas à être inversé.', 7),
    ('59f87042-1c5a-5ea3-8ef6-702f43648cf5'::uuid, 'b1c02179-f576-52e9-9da6-2254de57d679'::uuid, 'On peut écrire « Did you went? » au passé.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'DID porte déjà le passé : le verbe reste à la base verbale.', 8),
    ('208e4589-db5e-5d7a-98f5-4d884be6a0c7'::uuid, '1ec7b402-0066-51b6-8092-8649b95a460a'::uuid, 'D’où vient l’obligation exprimée par « must » ?', 'mcq', '["De celui qui parle","Du règlement extérieur","D’une loi écrite","De personne"]'::jsonb, 0, '« Have to » exprime, lui, une contrainte extérieure.', 1),
    ('b066c263-3850-5a0d-9745-1e79c8fdd076'::uuid, '1ec7b402-0066-51b6-8092-8649b95a460a'::uuid, 'Que signifie « You mustn’t smoke here » ?', 'mcq', '["Il est interdit de fumer ici","Tu n’es pas obligé de fumer","Tu peux fumer si tu veux","Tu devrais fumer dehors"]'::jsonb, 0, '« Mustn’t » exprime l’interdiction.', 2),
    ('d9e09c13-4597-5fc4-a99b-95346b395632'::uuid, '1ec7b402-0066-51b6-8092-8649b95a460a'::uuid, 'Que signifie « You don’t have to come » ?', 'mcq', '["Tu n’es pas obligé de venir","Il t’est interdit de venir","Tu dois venir","Tu devrais venir"]'::jsonb, 0, 'Absence d’obligation, pas interdiction.', 3),
    ('a5f001d5-e002-5849-930c-e6ee4714cc85'::uuid, '1ec7b402-0066-51b6-8092-8649b95a460a'::uuid, 'Comment exprime-t-on l’obligation au passé ?', 'mcq', '["had to","musted","must have","was must"]'::jsonb, 0, '« Must » n’a pas de forme passée.', 4),
    ('c74c1890-30f3-5518-8fea-2583a51996e2'::uuid, '1ec7b402-0066-51b6-8092-8649b95a460a'::uuid, 'Quelle phrase est correcte ?', 'mcq', '["She must go now.","She musts go now.","She must to go now.","She must going now."]'::jsonb, 0, 'Un modal est invariable et se construit sans « to ».', 5),
    ('d1847327-e066-5112-bfea-e1ac3d5916f9'::uuid, '1ec7b402-0066-51b6-8092-8649b95a460a'::uuid, 'Comment interroge-t-on avec « have to » ?', 'mcq', '["Do you have to go?","Have you to go?","Do you must go?","Are you have to go?"]'::jsonb, 0, '« Have to » se comporte comme un verbe lexical : il demande « do ».', 6),
    ('bc830355-d70b-54b9-94e7-28333d8c0923'::uuid, '1ec7b402-0066-51b6-8092-8649b95a460a'::uuid, 'Quel modal exprime le conseil plutôt que l’obligation ?', 'mcq', '["should","must","have to","need to"]'::jsonb, 0, '« You should see a doctor. »', 7),
    ('332b26df-72e0-54b9-bb77-0ab8187d3817'::uuid, '1ec7b402-0066-51b6-8092-8649b95a460a'::uuid, '« Mustn’t » et « don’t have to » ont le même sens.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le premier interdit, le second dispense : c’est le piège du chapitre.', 8),
    ('15346d1c-10d4-5828-9708-fa2d1279a301'::uuid, '4c864126-9cbb-5455-9030-00a03f6a823a'::uuid, 'Quel modal exprime la capacité au présent ?', 'mcq', '["can","must","should","may"]'::jsonb, 0, '« I can swim. »', 1),
    ('af7cf263-ccdb-53fb-b4c9-65ccad29f7f7'::uuid, '4c864126-9cbb-5455-9030-00a03f6a823a'::uuid, 'Quelle phrase est correcte ?', 'mcq', '["She can speak three languages.","She cans speak three languages.","She can to speak three languages.","She can speaking three languages."]'::jsonb, 0, 'Un modal est invariable et se construit sans « to ».', 2),
    ('6572a4ab-8fca-532e-86e2-4c7eb7ef7b9c'::uuid, '4c864126-9cbb-5455-9030-00a03f6a823a'::uuid, 'Comment exprime-t-on une capacité passée générale ?', 'mcq', '["could","can","was can","could to"]'::jsonb, 0, '« I could swim when I was five. »', 3),
    ('f6ce4a62-94de-517a-8360-0cdda002af17'::uuid, '4c864126-9cbb-5455-9030-00a03f6a823a'::uuid, 'Comment exprime-t-on une réussite ponctuelle au passé ?', 'mcq', '["was/were able to","could","can","must have"]'::jsonb, 0, '« He was able to open the door » : il y est parvenu cette fois-là.', 4),
    ('bbb5a870-f44f-5806-9464-1a042b5a4471'::uuid, '4c864126-9cbb-5455-9030-00a03f6a823a'::uuid, 'Comment exprime-t-on une capacité future ?', 'mcq', '["will be able to","will can","can will","shall can"]'::jsonb, 0, 'Deux modaux ne peuvent jamais se suivre.', 5),
    ('d4f89429-7f0f-5f17-bbbb-fd7cbcb68adb'::uuid, '4c864126-9cbb-5455-9030-00a03f6a823a'::uuid, 'Comment traduit-on « Je vois la mer d’ici » ?', 'mcq', '["I can see the sea from here.","I see the sea from here, can.","I am seeing the sea from here.","I could see the sea from here."]'::jsonb, 0, 'Avec les verbes de perception, « can » ne se traduit pas en français.', 6),
    ('b6b35019-294e-5abd-ad28-679004875a9b'::uuid, '4c864126-9cbb-5455-9030-00a03f6a823a'::uuid, 'Quelle formule est la plus polie pour demander de l’aide ?', 'mcq', '["Could you help me, please?","Can you help me!","You must help me.","You help me?"]'::jsonb, 0, '« Could » atténue la demande.', 7),
    ('6ec66281-07e0-5ed8-895a-bdfc3a3ef23a'::uuid, '4c864126-9cbb-5455-9030-00a03f6a823a'::uuid, 'On peut dire « I will can swim » pour exprimer une capacité future.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Deux modaux ne se suivent jamais : « I will be able to swim ».', 8),
    ('d627baa4-6195-5fc7-8313-f8265713eb89'::uuid, 'ac639c3c-2af0-5955-87e1-3a3dfabfa197'::uuid, 'Quel modal est le plus formel pour demander la permission ?', 'mcq', '["may","can","could","must"]'::jsonb, 0, '« May I come in? » s’emploie à l’écrit ou avec un adulte.', 1),
    ('a5086c24-9059-5473-8d59-bad5d1ece546'::uuid, 'ac639c3c-2af0-5955-87e1-3a3dfabfa197'::uuid, 'Quelle phrase demande poliment une permission ?', 'mcq', '["Could I borrow your pen?","You could borrow my pen.","I can borrow your pen.","Must I borrow your pen?"]'::jsonb, 0, '« Could » sert à demander, jamais à accorder.', 2),
    ('43eb8069-f074-5f32-9c35-eaf96ffff121'::uuid, 'ac639c3c-2af0-5955-87e1-3a3dfabfa197'::uuid, 'Comment accorde-t-on une permission de façon familière ?', 'mcq', '["You can use my phone.","You could use my phone.","You may not use my phone.","You must use my phone."]'::jsonb, 0, '« Could » n’accorde pas : il suggérerait.', 3),
    ('aa80a5bf-414e-5f53-8146-2f9b42c29192'::uuid, 'ac639c3c-2af0-5955-87e1-3a3dfabfa197'::uuid, 'Comment exprime-t-on une permission au passé ?', 'mcq', '["I was allowed to go.","I could to go.","I may went.","I can went."]'::jsonb, 0, '« Could » ne convient pas pour une permission accordée une fois.', 4),
    ('a6f5e2d4-f09e-5d2a-baf1-b50d6ee20b84'::uuid, 'ac639c3c-2af0-5955-87e1-3a3dfabfa197'::uuid, 'Que signifie « You mustn’t touch it » ?', 'mcq', '["C’est une interdiction stricte","Tu n’es pas obligé d’y toucher","Tu peux y toucher","Tu devrais y toucher"]'::jsonb, 0, 'Plus fort que « you can’t ».', 5),
    ('35356608-0325-5597-a27e-61a74dfd5d64'::uuid, 'ac639c3c-2af0-5955-87e1-3a3dfabfa197'::uuid, 'Quelle forme se conjugue à tous les temps ?', 'mcq', '["be allowed to","may","can","could"]'::jsonb, 0, '« I will be allowed to vote at 18. »', 6),
    ('08282cbd-dd27-51af-aa2f-7297dab9780d'::uuid, 'ac639c3c-2af0-5955-87e1-3a3dfabfa197'::uuid, 'Quelle formule apparaît dans un règlement écrit ?', 'mcq', '["Students may not use their phones.","Students can’t use their phones, ok?","Students could not use phones.","Students don’t use phones."]'::jsonb, 0, '« May not » appartient au registre formel.', 7),
    ('569a9975-d750-5339-9253-32fb15e5807d'::uuid, 'ac639c3c-2af0-5955-87e1-3a3dfabfa197'::uuid, '« Could » sert aussi bien à demander qu’à accorder une permission.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Pour accorder, on emploie « can » ou « may ».', 8),
    ('155fc683-0eb3-5378-b5c5-1b431f50e6b7'::uuid, 'dd2a9b0f-802b-54bf-b41e-05bf5e538d25'::uuid, 'Quel modal exprime le conseil de base ?', 'mcq', '["should","must","can","may"]'::jsonb, 0, '« You should revise for the test. »', 1),
    ('a723d6c7-82a0-5b2b-a004-fe41e5b0d9fc'::uuid, 'dd2a9b0f-802b-54bf-b41e-05bf5e538d25'::uuid, 'Quelle phrase est correcte ?', 'mcq', '["You should revise tonight.","You should to revise tonight.","You shoulds revise tonight.","You should revising tonight."]'::jsonb, 0, 'Un modal est suivi de la base verbale sans « to ».', 2),
    ('18a09456-8b36-50ad-b513-94f4d5f4326b'::uuid, 'dd2a9b0f-802b-54bf-b41e-05bf5e538d25'::uuid, 'Quel modal du conseil se construit avec « to » ?', 'mcq', '["ought to","should","must","had better"]'::jsonb, 0, 'C’est le seul modal suivi de « to ».', 3),
    ('2d8cd10a-7d8b-5ac7-99fc-d0e7e4237b50'::uuid, 'dd2a9b0f-802b-54bf-b41e-05bf5e538d25'::uuid, 'Que signifie « You’d better hurry » ?', 'mcq', '["Tu ferais mieux de te dépêcher, sinon…","Tu pourrais te dépêcher","Tu es obligé de te dépêcher","Tu as bien fait de te dépêcher"]'::jsonb, 0, 'Un conseil pressant, avec une conséquence implicite.', 4),
    ('28d68215-caef-570e-9cfe-45116e24f630'::uuid, 'dd2a9b0f-802b-54bf-b41e-05bf5e538d25'::uuid, 'Comment se construit « had better » ?', 'mcq', '["had better + base verbale","had better + to + verbe","had better + verbe en -ing","had better + participe passé"]'::jsonb, 0, 'Malgré le « had », il n’y a ni « to » ni passé.', 5),
    ('59f6fa6b-340a-5479-a496-6d481af88cca'::uuid, 'dd2a9b0f-802b-54bf-b41e-05bf5e538d25'::uuid, 'Comment dit-on « Tu aurais dû me le dire » ?', 'mcq', '["You should have told me.","You should tell me.","You had better tell me.","You must have told me."]'::jsonb, 0, '« Should have + participe passé » exprime le reproche ou le regret.', 6),
    ('80fd7726-b3eb-5453-a8d8-87c017f9b91a'::uuid, 'dd2a9b0f-802b-54bf-b41e-05bf5e538d25'::uuid, 'Quelle formule propose un conseil sous forme de question ?', 'mcq', '["Why don’t you call her?","You must call her.","You’d better call her.","You ought to call her."]'::jsonb, 0, 'Elle adoucit le conseil en suggestion.', 7),
    ('ab7ae1c2-4af4-5416-970b-baf488dca888'::uuid, 'dd2a9b0f-802b-54bf-b41e-05bf5e538d25'::uuid, '« Had better » se conjugue au passé comme au présent.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est une expression figée qui vaut pour le présent et le futur.', 8),
    ('56847bbc-c42b-59da-b3e0-0cc67b69bc06'::uuid, '3ce11211-9f36-5a7b-9fac-28337c92ada0'::uuid, 'Comment se construit « Let’s » ?', 'mcq', '["Let’s + base verbale","Let’s + to + verbe","Let’s + verbe en -ING","Let’s + participe passé"]'::jsonb, 0, '« Let’s go to the cinema. »', 1),
    ('fe441531-7004-545a-89b3-de27de05fae8'::uuid, '3ce11211-9f36-5a7b-9fac-28337c92ada0'::uuid, 'Comment se construit « How about » ?', 'mcq', '["How about + nom ou verbe en -ING","How about + base verbale","How about + to + verbe","How about + participe passé"]'::jsonb, 0, '« How about going out tonight? »', 2),
    ('90c296ba-442b-5aa4-bf5d-fa8ad8e2f995'::uuid, '3ce11211-9f36-5a7b-9fac-28337c92ada0'::uuid, 'Quelle phrase est correcte ?', 'mcq', '["Why don’t we meet at six?","Why don’t we meeting at six?","Why we don’t meet at six?","Why don’t we to meet at six?"]'::jsonb, 0, '« Why don’t we » est suivi de la base verbale.', 3),
    ('09ebac97-9f8e-51db-a5b3-3d8ea73691a5'::uuid, '3ce11211-9f36-5a7b-9fac-28337c92ada0'::uuid, 'Que signifie « Shall we start? » ?', 'mcq', '["On commence ? — une proposition","Nous commencerons","Nous devons commencer","Nous avons commencé"]'::jsonb, 0, '« Shall » sert à proposer, surtout en anglais britannique.', 4),
    ('4e99d647-3bbc-590d-a211-5b89ca2b5855'::uuid, '3ce11211-9f36-5a7b-9fac-28337c92ada0'::uuid, 'Comment forme-t-on la négation de « Let’s » ?', 'mcq', '["Let’s not waste time.","Let’s don’t waste time.","Don’t let’s waste time.","Let’s no waste time."]'::jsonb, 0, '« Not » se place directement après « let’s ».', 5),
    ('eb247a47-3537-5767-97b3-5c6c69b42d85'::uuid, '3ce11211-9f36-5a7b-9fac-28337c92ada0'::uuid, 'Comment exprime-t-on une préférence ?', 'mcq', '["I’d rather stay home.","I’d rather to stay home.","I’d rather staying home.","I rather would stay home."]'::jsonb, 0, '« Would rather » est suivi de la base verbale.', 6),
    ('8d18719d-bffd-5389-a831-6313078cb8f5'::uuid, '3ce11211-9f36-5a7b-9fac-28337c92ada0'::uuid, 'Comment refuse-t-on poliment une suggestion ?', 'mcq', '["I’d rather not.","No.","I don’t want.","Never."]'::jsonb, 0, '« I’m afraid I can’t » convient également.', 7),
    ('64bce58a-0bda-5028-b15c-2db22426228b'::uuid, '3ce11211-9f36-5a7b-9fac-28337c92ada0'::uuid, 'On peut dire « How about go out tonight? ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '« How about » exige un nom ou un verbe en -ING : « How about going out? »', 8),
    ('c292803c-64ac-58b7-9e22-7c5eb9fec8a5'::uuid, 'e080884a-59a8-57da-9a20-ca7e881b989c'::uuid, 'Quelle construction suit « would like » ?', 'mcq', '["to + verbe","la base verbale","le verbe en -ING","le participe passé"]'::jsonb, 0, '« I’d like to travel. »', 1),
    ('49b455d1-99f0-57f1-b47a-9844ee7029e8'::uuid, 'e080884a-59a8-57da-9a20-ca7e881b989c'::uuid, 'Quel temps suit « wish » pour un regret sur le présent ?', 'mcq', '["Le prétérit","Le présent","Le past perfect","Le futur"]'::jsonb, 0, '« I wish I had more time. »', 2),
    ('6599796e-a8db-510a-940c-1c750bd27944'::uuid, 'e080884a-59a8-57da-9a20-ca7e881b989c'::uuid, 'Quel temps suit « wish » pour un regret sur le passé ?', 'mcq', '["Le past perfect","Le prétérit","Le present perfect","Le conditionnel"]'::jsonb, 0, '« I wish I had studied harder. »', 3),
    ('1763b18e-8c61-5a5c-948e-6407ec82d39d'::uuid, 'e080884a-59a8-57da-9a20-ca7e881b989c'::uuid, 'Comment exprime-t-on le souhait qu’une situation change ?', 'mcq', '["wish + would","wish + will","wish + can","wish + must"]'::jsonb, 0, '« I wish it would stop raining. »', 4),
    ('a087bb97-e24a-5530-8a8a-a0f8ccb90b9b'::uuid, 'e080884a-59a8-57da-9a20-ca7e881b989c'::uuid, 'Quelle phrase exprime un regret sur le présent ?', 'mcq', '["I wish I were taller.","I wish I am taller.","I wish I will be taller.","I wish I had been taller."]'::jsonb, 0, '« Were » s’emploie à toutes les personnes dans cette forme irréelle.', 5),
    ('4bb1664c-7a5d-5110-81c3-1aaf12a62194'::uuid, 'e080884a-59a8-57da-9a20-ca7e881b989c'::uuid, 'Quelle expression renforce le regret exprimé par « wish » ?', 'mcq', '["If only","As well","Even so","At last"]'::jsonb, 0, '« If only I had listened! »', 6),
    ('0703378b-afce-52bf-aad5-c02a44919eac'::uuid, 'e080884a-59a8-57da-9a20-ca7e881b989c'::uuid, 'Comment dit-on « J’aurais dû te le dire » ?', 'mcq', '["I should have told you.","I should tell you.","I wish I tell you.","I would like to tell you."]'::jsonb, 0, '« Should have + participe passé » exprime le regret.', 7),
    ('fba676b5-6f12-50ea-906e-585873edc78a'::uuid, 'e080884a-59a8-57da-9a20-ca7e881b989c'::uuid, '« I wish you a happy birthday » suit la règle du recul d’un temps.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Souhaiter quelque chose À quelqu’un est la seule construction de « wish » qui n’y est pas soumise.', 8),
    ('382db183-f7e8-5787-b8f8-218bed628b4e'::uuid, '76cb32f6-15f8-5eb1-863e-9fc21db53709'::uuid, 'Quel modal exprime la quasi-certitude positive ?', 'mcq', '["must","might","can’t","may"]'::jsonb, 0, '« He must be tired » : j’en suis presque sûr.', 1),
    ('886d9de8-d384-5f58-8a9b-babe5f76d0d4'::uuid, '76cb32f6-15f8-5eb1-863e-9fc21db53709'::uuid, 'Quel modal exprime la certitude négative ?', 'mcq', '["can’t","mustn’t","shouldn’t","may not"]'::jsonb, 0, '« He can’t be serious! » — ce n’est pas possible.', 2),
    ('d5a967e3-6f27-5eed-b85f-8628250de5b9'::uuid, '76cb32f6-15f8-5eb1-863e-9fc21db53709'::uuid, 'Quels modaux expriment une simple possibilité ?', 'mcq', '["may, might, could","must, should","can’t, mustn’t","will, shall"]'::jsonb, 0, '« It may rain », « it might rain ».', 3),
    ('d7327ef1-7c1d-5e67-aa10-1cbea363c489'::uuid, '76cb32f6-15f8-5eb1-863e-9fc21db53709'::uuid, 'Comment exprime-t-on une déduction sur le passé ?', 'mcq', '["modal + have + participe passé","modal + prétérit","modal + to + verbe","modal + verbe en -ING"]'::jsonb, 0, '« He must have missed the train. »', 4),
    ('8db5c70d-52eb-5b8f-9ccd-4f39aca1a744'::uuid, '76cb32f6-15f8-5eb1-863e-9fc21db53709'::uuid, 'Que signifie « She may have forgotten » ?', 'mcq', '["Elle a peut-être oublié","Elle doit oublier","Elle ne peut pas avoir oublié","Elle aurait dû oublier"]'::jsonb, 0, '« May have » exprime une possibilité passée.', 5),
    ('be8456dc-242e-5b0a-9e37-e1546d7aaa64'::uuid, '76cb32f6-15f8-5eb1-863e-9fc21db53709'::uuid, 'Quel modal marque la probabilité la plus faible ?', 'mcq', '["might","must","should","will"]'::jsonb, 0, 'Il est un cran en dessous de « may ».', 6),
