    ('f1025392-275d-58d5-880a-a8e88fc174ba'::uuid, '76cb32f6-15f8-5eb1-863e-9fc21db53709'::uuid, 'La négation de la certitude « must » est « mustn’t ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est « can’t » : « mustn’t » garderait le sens d’interdiction.', 8),
