    ('b76b9163-3d22-58b6-bbcd-8e75bd425822'::uuid, '5850f4a0-d394-5a48-84a6-c63123e7b5da'::uuid, 'Que signifie « I got him to help me » ?', 'mcq', '["J’ai réussi à le convaincre de m’aider","Je l’ai obligé à m’aider","Je l’ai laissé m’aider","Il m’a aidé sans que je demande"]'::jsonb, 0, '« Get + to + verbe » suppose un effort de persuasion.', 5),
    ('8d3593ae-d38c-56a1-b36c-4e7909d722e7'::uuid, '5850f4a0-d394-5a48-84a6-c63123e7b5da'::uuid, 'Que devient « make » à la voix passive ?', 'mcq', '["Il est suivi de « to » : I was made to wait.","Il reste sans « to »","Il devient « let »","Il n’a pas de passif"]'::jsonb, 0, 'C’est la seule situation où « make » prend « to ».', 6),
