    ('b4b5869f-cd82-52a6-8015-a81656aae941'::uuid, '6f1fdd27-51b6-5bf9-9994-54c9394558c9'::uuid, 'Que signifie « look after » ?', 'mcq', '["S’occuper de","Chercher","Regarder derrière","Ressembler à"]'::jsonb, 0, '« Look for » signifie chercher.', 2),
    ('a4e31ac2-40a6-560b-95c0-7e3176553794'::uuid, '6f1fdd27-51b6-5bf9-9994-54c9394558c9'::uuid, 'Où se place obligatoirement un pronom complément avec un verbe à particule ?', 'mcq', '["Avant la particule","Après la particule","En début de phrase","À la fin de la phrase"]'::jsonb, 0, '« Turn it on », jamais « turn on it ».', 3),
