    ('fda5bc83-e22f-5e5e-bc42-4589a48ddd55'::uuid, '6f1fdd27-51b6-5bf9-9994-54c9394558c9'::uuid, 'Que signifie « put off » ?', 'mcq', '["Reporter","Éteindre définitivement","Enlever un vêtement","Déposer quelqu’un"]'::jsonb, 0, '« Put on » signifie mettre un vêtement.', 5),
    ('ce571896-eddf-5a80-b1e8-3b2db0ef93dc'::uuid, '6f1fdd27-51b6-5bf9-9994-54c9394558c9'::uuid, 'Quelle est la différence entre une particule et une préposition ?', 'mcq', '["La particule peut être séparée du verbe, la préposition non","La préposition change le sens, pas la particule","La particule se place toujours en fin de phrase","Il n’y a aucune différence"]'::jsonb, 0, 'Le test : peut-on glisser le complément au milieu ?', 6),
