    ('cd1e4999-be8a-5d53-a9ac-6ed56d4a6d26'::uuid, '9cf3af5e-0660-5da2-ba21-1dd608003a27'::uuid, 'Quelle forme suit un modal ?', 'mcq', '["La base verbale","to + verbe","Le verbe en -ING","Le participe passé"]'::jsonb, 0, '« You must go », « I can swim ».', 4),
    ('12d1b4a1-9ff5-5f6d-a23b-3c4c094ceaaf'::uuid, '9cf3af5e-0660-5da2-ba21-1dd608003a27'::uuid, 'Quelle est la différence entre « stop to smoke » et « stop smoking » ?', 'mcq', '["Le premier signifie s’arrêter pour fumer, le second arrêter de fumer","Les deux sont identiques","Le premier est incorrect","Le second signifie s’arrêter de marcher"]'::jsonb, 0, 'Le choix de la forme change complètement le sens.', 5),
