    ('7a710db6-3291-5f14-9dfc-9a73f804b238'::uuid, 'efc1f608-8d79-5710-8bc9-f04519844fe0'::uuid, 'Que signifie « hardly » ?', 'mcq', '["À peine","Durement","Fortement","Rapidement"]'::jsonb, 0, '« I can hardly hear you » signifie « je t’entends à peine ».', 3),
