    ('bc440f0f-84e6-5a5f-85ed-e5cd3d438868'::uuid, 'cbff9b7a-2585-5397-89d9-9955ea33bbdd'::uuid, 'Quelle phrase est correcte ?', 'mcq', '["She doesn’t work here.","She doesn’t works here.","She don’t work here.","She not works here."]'::jsonb, 0, 'DOES porte la marque de la personne.', 4),
    ('ce057756-0560-5078-8837-df9d5ed0ccc7'::uuid, 'cbff9b7a-2585-5397-89d9-9955ea33bbdd'::uuid, 'Quel verbe n’accepte pas la forme en -ING ?', 'mcq', '["know","work","run","read"]'::jsonb, 0, 'Les verbes d’état restent au présent simple.', 5),
    ('75a3be7b-1e99-5415-8f24-92b91f837aec'::uuid, 'cbff9b7a-2585-5397-89d9-9955ea33bbdd'::uuid, 'Comment exprime-t-on un projet déjà organisé ?', 'mcq', '["We are meeting Tom tonight.","We meet Tom tonight.","We will meet Tom tonight, maybe.","We are meet Tom tonight."]'::jsonb, 0, 'Le présent en BE + -ING vaut pour l’avenir organisé.', 6),
