    ('4440e725-d82d-50fd-9cd9-943990e6d2f9'::uuid, 'cbff9b7a-2585-5397-89d9-9955ea33bbdd'::uuid, '« I am knowing the answer » est une phrase correcte.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '« Know » est un verbe d’état : « I know the answer ».', 8),
