    ('702ee0f7-0b32-571e-988d-d527cbb5f31c'::uuid, '4a56a617-3f67-5e41-8b76-921d5c52d9da'::uuid, 'Quel est le prétérit de « study » ?', 'mcq', '["studied","studyed","studed","studying"]'::jsonb, 0, 'Consonne + y donne -ied.', 2),
    ('93244347-c24b-55c7-acb2-648615ae7ec6'::uuid, '4a56a617-3f67-5e41-8b76-921d5c52d9da'::uuid, 'Quel est le prétérit de « stop » ?', 'mcq', '["stopped","stoped","stopt","stopping"]'::jsonb, 0, 'La consonne finale double après une voyelle courte accentuée.', 3),
    ('01ebae9f-640f-5926-a423-f459592a8fff'::uuid, '4a56a617-3f67-5e41-8b76-921d5c52d9da'::uuid, 'Quelle phrase est correcte ?', 'mcq', '["I didn’t go to school.","I didn’t went to school.","I not went to school.","I don’t went to school."]'::jsonb, 0, 'DID porte le passé, le verbe reste à la base verbale.', 4),
    ('87d0c980-391b-5d8a-8cb7-c86f4c5961c5'::uuid, '4a56a617-3f67-5e41-8b76-921d5c52d9da'::uuid, 'Comment se conjugue le prétérit régulier selon les personnes ?', 'mcq', '["Il est identique à toutes les personnes","Il prend un -s à la troisième personne","Il change à chaque personne","Il n’existe qu’à la première personne"]'::jsonb, 0, 'Seul « be » fait exception, avec was et were.', 5),
    ('55e34dd8-2ec7-523c-976e-41686ab76f4f'::uuid, '4a56a617-3f67-5e41-8b76-921d5c52d9da'::uuid, 'Que signifie « I used to play football » ?', 'mcq', '["Je jouais au football autrefois, ce n’est plus le cas","Je joue habituellement au football","J’ai l’habitude d’utiliser un ballon","Je vais jouer au football"]'::jsonb, 0, '« Used to » marque une habitude passée révolue.', 6),
